entries.goodExample:
limit := make(chan struct{}, 8)
var wg sync.WaitGroup
for _, job := range jobs {
	limit <- struct{}{}
	wg.Add(1)
	go func(job Job) {
		defer wg.Done()
		defer func() { <-limit }()
		run(job)
	}(job)
}
wg.Wait()

