}

ctx, cancel := context.WithCancel(parent)
done := make(chan struct{})
go func() {
	defer close(done)
	for {
		select {
		case <-ctx.Done(): return
		case job, ok := <-jobs:
			if !ok { return }
			process(job) // 此操作会在有限时间内完成
		}
	}
}()
// 关闭时：发出停止信号并等待退出
cancel()
<-done

